import sys, re
from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.out=[]; self.skip=0; self.math=0
        self.block={'p','div','h1','h2','h3','h4','h5','h6','li','tr','br','section','figcaption','table','blockquote','dd','dt'}
    def handle_starttag(self,tag,attrs):
        a=dict(attrs)
        if tag in ('script','style'): self.skip+=1
        if tag=='math':
            self.math+=1
            if a.get('alttext'): self.out.append(' $'+a['alttext']+'$ ')
        if tag in self.block: self.out.append('\n')
        if tag in ('h1','h2','h3','h4'): self.out.append('\n## ')
    def handle_endtag(self,tag):
        if tag in ('script','style'): self.skip-=1
        if tag=='math': self.math-=1
        if tag in self.block: self.out.append('\n')
    def handle_data(self,d):
        if self.skip or self.math: return
        self.out.append(d)
p=P(); p.feed(open(sys.argv[1],encoding='utf-8').read())
t=''.join(p.out); t=re.sub(r'[ \t]+',' ',t); t=re.sub(r'\n\s*\n+','\n\n',t)
open(sys.argv[2],'w').write(t)
EOF
python3 html2txt.py paper.html paper.txt && wc -l -w paper.txt && grep -n '^## ' paper.txt | head -60

