// What ingestion needs from the outside world, as the narrowest interfaces that say it.
//
// Three of the pipeline's stages are model or vector-store calls. Behind these seams they
// are scriptable, so a case can prove what the pipeline does with an embedding without
// asserting anything about what an embedding is — and phase 5 can change the model, the
// index or the prompt without touching a case.

/** Turns text into a vector. One call per utterance, so cost is linear in the corpus. */
export type Embedder = {
  /** Identifies which model produced a vector; two models' vectors are not comparable. */
  readonly modelVersion: string;
  embed(text: string): Promise<number[]>;
};

export type Neighbour = {
  /** The utterance the vector belongs to. */
  id: string;
  /** Distance, not similarity: smaller is nearer, so a threshold reads the obvious way. */
  distance: number;
};

/** The vector index. D1 has no vector type and the retrieval needed is nearest-neighbour. */
export type Vectors = {
  /** Keyed on the utterance id, so writing the same utterance twice stores one vector. */
  upsert(utteranceId: string, vector: number[]): Promise<void>;
  has(utteranceId: string): Promise<boolean>;
  nearest(vector: number[], limit: number): Promise<Neighbour[]>;
};

export type Placement = {
  /** Where on the subject's axis, -1..1. */
  position: number;
  /** 0..1. */
  confidence: number;
};

/**
 * Places one utterance on its subject's axis. A separate call from the embedding on
 * purpose: distance measures aboutness, not agreement, so position is a judgment that has
 * to be made and recorded rather than read off the geometry.
 */
export type StanceModel = {
  readonly modelVersion: string;
  readonly promptVersion: string;
  place(input: { text: string; neighbours: { text: string; position: number }[] }): Promise<Placement>;
};
===== PIPELINE =====
// One passage, all the way in: merge it into an utterance, embed it, put it in a subject,
// and record where it stands. The chain that turns a document into something the analysis
// can reason about, in one module so a backfill Workflow and the nightly cron run exactly
// the same code (#34 phase 4).
//
// Two properties shape all of it.
//
// **Every stage is keyed on something the payload determines**, so replaying a payload
// finds its own work already done rather than writing a second copy. Backfilling decades
// means replaying constantly — a parser fix re-runs every cached payload, a failed
// Workflow step re-runs its slice — and duplicates would fill a persona's timeline with
// copies of one sentence that the analysis then reads as agreement.
//
// **Each stage commits before the next starts**, and a failure is reported rather than
// thrown. Embedding and stance are model calls that rate-limit, time out and cost money;
// losing the utterance because the stance call failed would mean re-fetching, re-extracting
// and re-paying for the whole chain on the next attempt.
import type { Corpus, ReportedUtterance } from '../corpus/store.ts';
import type { Utterance } from '../../shared/types.ts';
import type { Embedder, StanceModel, Vectors } from './ports.ts';

/**
 * How near an utterance must fall to join an existing subject rather than open one.
 *
 * A policy number, not a fact: too low and one subject splinters into near-duplicates, too
 * high and unrelated things merge and every stance series becomes noise. Phase 5 tunes it
 * against a real corpus; until then it is deliberately conservative — splintering is
 * recoverable by merging subjects later, and a merged subject has already destroyed the
 * distinction.
 */
export const NEAR_ENOUGH = 0.35;

/** How many neighbours the stance model is shown to infer the subject's axis from. */
const AXIS_SAMPLE = 5;

/** The stages, in order. A run reports the last one it completed. */
export const STAGES = ['merged', 'embedded', 'assigned', 'placed'] as const;
export type Stage = (typeof STAGES)[number];

export type IngestOutcome = {
  utterance: Utterance;
  /** False when this passage was already held as an utterance and only added an attestation. */
  minted: boolean;
  /** The last stage that committed. Anything after it is still to do on a later pass. */
  reached: Stage;
  /** Why it stopped short, when it did. The caller decides whether that is worth a retry. */
  stoppedBecause: string | null;
};

export type IngestDeps = {
  corpus: Corpus;
  embedder: Embedder;
  vectors: Vectors;
  stance: StanceModel;
};

/**
 * Runs one reported passage through the whole chain. Never throws for a stage failure —
 * the outcome says how far it got, which is what a Workflow step reads to decide whether
 * to retry, and what a caller sums to report a pass.
 */
export async function ingest(deps: IngestDeps, reported: ReportedUtterance): Promise<IngestOutcome> {
  // 1. Merge. Idempotent on (speaker, folded words, date, venue): the same speech from a
  //    second document becomes another attestation of the utterance we already hold.
  const { utterance, merged } = await deps.corpus.recordReported(reported);
  const outcome: IngestOutcome = { utterance, minted: !merged, reached: 'merged', stoppedBecause: null };

  // 2. Embed. Keyed on the utterance id, so a replay neither re-pays the model nor writes
  //    a second vector. An utterance that merged into an existing one is already embedded.
  let vector: number[];
  try {
    if (await deps.vectors.has(utterance.id)) {
      outcome.reached = 'embedded';
      // Already embedded means already assigned and placed by the pass that embedded it,
      // unless that pass stopped in between — so the stages below still run and find their
      // own work done.
      vector = [];
    } else {
      vector = await deps.embedder.embed(utterance.text);
      await deps.vectors.upsert(utterance.id, vector);
      outcome.reached = 'embedded';
    }
  } catch (error) {
    outcome.stoppedBecause = `embed: ${String(error)}`;
    return outcome;
  }

  // 3. Assign. The nearest existing subject if anything is near enough, otherwise a new
  //    one — which is the whole of "subjects are discovered": nothing is edited anywhere
  //    for the corpus to become able to be about something new.
  let clusterId: string;
  try {
    const existing = await deps.corpus.clusterOf(utterance.id);
    if (existing) {
      clusterId = existing.clusterId;
    } else {
      const near = vector.length ? await nearestOther(deps, vector, utterance.id) : null;
      const assigned = await deps.corpus.assignToCluster(
        utterance.id,
        near && near.distance <= NEAR_ENOUGH ? await subjectOf(deps, near.id) : null,
        near?.distance ?? null,
      );
      clusterId = assigned.clusterId;
    }
    outcome.reached = 'assigned';
  } catch (error) {
    outcome.stoppedBecause = `assign: ${String(error)}`;
    return outcome;
  }

  // 4. Place. Idempotent on (utterance, model, prompt): the same judgment is not re-paid
  //    for, and a new model or prompt writes its own row beside the old one.
  try {
    const already = await deps.corpus.stancesFor(utterance.id);
    const same = already.find(
      (stance) => stance.modelVersion === deps.stance.modelVersion && stance.promptVersion === deps.stance.promptVersion,
    );
    if (!same) {
      const placement = await deps.stance.place({
        text: utterance.text,
        neighbours: await axisOf(deps, clusterId, utterance.id),
      });
      await deps.corpus.recordStance({
        utteranceId: utterance.id,
        clusterId,
        position: placement.position,
        confidence: placement.confidence,
        modelVersion: deps.stance.modelVersion,
        promptVersion: deps.stance.promptVersion,
      });
    }
    outcome.reached = 'placed';
  } catch (error) {
    outcome.stoppedBecause = `place: ${String(error)}`;
  }

  return outcome;
}

/** The nearest vector that is not this utterance's own. */
async function nearestOther(deps: IngestDeps, vector: number[], self: string) {
  const found = await deps.vectors.nearest(vector, 2);
  return found.find((neighbour) => neighbour.id !== self) ?? null;
}

/** The subject an already-ingested utterance belongs to, if it has one yet. */
async function subjectOf(deps: IngestDeps, utteranceId: string): Promise<string | null> {
  return (await deps.corpus.clusterOf(utteranceId))?.clusterId ?? null;
}

/**
 * What the subject's axis already looks like: a sample of its placed members, so the model
 * places this utterance against the positions its neighbours were given rather than against
 * a scale it invents per call.
 */
async function axisOf(deps: IngestDeps, clusterId: string, self: string) {
  const members = (await deps.corpus.clusterMembers(clusterId))
    .filter((member) => member.utteranceId !== self)
    .slice(0, AXIS_SAMPLE);

  const axis: { text: string; position: number }[] = [];
  for (const member of members) {
    const utterance = await deps.corpus.getUtterance(member.utteranceId);
    const stance = (await deps.corpus.stancesFor(member.utteranceId)).find(
      (recorded) => recorded.modelVersion === deps.stance.modelVersion && recorded.promptVersion === deps.stance.promptVersion,
    );
    if (utterance && stance) axis.push({ text: utterance.text, position: stance.position });
  }
  return axis;
}
===== SERIES =====
// Reading a stance series for the two things it can honestly say: that one utterance sits
// apart from the persona's usual position on a subject, and that the position moved.
//
// Pure functions over a series, with no store and no model in sight — which is what lets
// a case plant a step change or an outlier and assert exactly what comes back. The
// thresholds are the whole of the policy, so they are named, defaulted in one place, and
// overridable per call.

/** One point: where the persona stood, and when. */
export type Point = {
  utteranceId: string;
  /** -1..1 on the subject's axis. */
  position: number;
  /**
   * When it was said. Null means the source established no date — such a point is kept in
   * the series (it is still something the persona said) but cannot bound an interval.
   */
  saidAt: string | null;
};

export type Thresholds = {
  /**
   * How far from the prevailing position an utterance must sit to be an anomaly, in
   * absolute axis units. The axis runs -1..1, so this is a quarter of its full width:
   * enough to exclude ordinary variation in how a position is worded on a given day.
   */
  anomalyDistance: number;
  /**
   * How far the level must move across a candidate change point to be a trend change.
   * Higher than `anomalyDistance` on purpose — a trend is a claim about a persona's whole
   * position, and a weaker bar would report every noisy stretch as a change of mind.
   */
  stepSize: number;
  /**
   * The fewest points either side of a change point. Two points cannot establish a level,
   * so a "change" between two singletons is one utterance either side of a gap.
   */
  minimumRun: number;
};

export const DEFAULTS: Thresholds = { anomalyDistance: 0.5, stepSize: 0.6, minimumRun: 2 };

/** Ordered oldest first, undated points last — a series is a claim about time. */
export function inTimeOrder(points: Point[]): Point[] {
  return [...points].sort((a, b) => {
    if (a.saidAt && b.saidAt) return a.saidAt.localeCompare(b.saidAt) || a.utteranceId.localeCompare(b.utteranceId);
    if (a.saidAt) return -1;
    if (b.saidAt) return 1;
    return a.utteranceId.localeCompare(b.utteranceId);
  });
}

const median = (values: number[]): number => {
  const sorted = [...values].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? (sorted[middle] as number) : ((sorted[middle - 1] as number) + (sorted[middle] as number)) / 2;
};

export type Anomaly = { utteranceId: string; position: number; prevailing: number; distance: number };

/**
 * How many other utterances may share a candidate's neighbourhood before it stops being an
 * anomaly and becomes a second position the persona also holds. A fraction of the series
 * rather than a count, so it means the same thing on a series of six and one of six hundred.
 */
const COMPANY = 0.15;

/**
 * Utterances sitting far from where the persona otherwise stands on this subject — one out
 * of step, not a position they hold as well.
 *
 * Two rules, and the second is the one that is easy to miss. The prevailing position is the
 * median of *everything else*, recomputed per candidate, because a baseline including the
 * candidate is pulled towards it and lets a far-enough outlier hide behind it. And a
 * candidate with company is not an outlier: a series that has genuinely split into two
 * levels is what a **trend change** looks like, and without this every point in one would
 * be reported as an anomaly as well.
 */
export function anomaliesIn(points: Point[], thresholds: Thresholds = DEFAULTS): Anomaly[] {
  // Below four, "the others" is one or two points — a baseline too thin to call anything
  // a deviation from.
  if (points.length < 4) return [];

  const alone = Math.floor((points.length - 1) * COMPANY);
  const found: Anomaly[] = [];
  for (const [index, point] of points.entries()) {
    const others = points.filter((_, other) => other !== index);
    const prevailing = median(others.map((other) => other.position));
    const distance = Math.abs(point.position - prevailing);
    if (distance < thresholds.anomalyDistance) continue;

    const company = others.filter(
      (other) => Math.abs(other.position - point.position) < thresholds.anomalyDistance,
    ).length;
    if (company > alone) continue;

    found.push({ utteranceId: point.utteranceId, position: point.position, prevailing, distance });
  }
  return found;
}

export type TrendChange = {
  /** The last utterance before the change, and the first after it. */
  before: Point;
  after: Point;
  /** The levels either side, as the median of each run. */
  fromLevel: number;
  toLevel: number;
  /** The interval the change falls in. Null when either side of it is undated. */
  changed: { after: string; before: string } | null;
};

/**
 * The single largest step in the series, when it is large enough to be one.
 *
 * One change point, not several: a series with two genuine steps is a persona who moved
 * twice, and reporting the larger one now leaves the other to be found once the first is
 * accounted for. Reporting both from one pass would need a segmentation this does not do,
 * and claiming it would be a claim the method cannot support.
 */
