+        : measured.similarity === 1
+          ? 'equivalent'
+          : covered
+            ? 'entails'
+            : measured.similarity > 0
+              ? 'same-subject'
+              : 'unrelated';
+      return {
+        relation,
+        score: measured.similarity,
+        trail: { premises: measured.premises.classes, consequences: measured.consequences.classes },
+      };
+    },
